package com.appnexus.platform.persistence.organization;
import com.appnexus.platform.organization.OrganizationStructure;
import com.appnexus.platform.tenant.VerifiedTenantContext;
import java.nio.ByteBuffer; import java.sql.Timestamp; import java.time.Instant; import java.util.*;
import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.context.request.*;
/** 组织领域持久化适配器；跨聚合写入在事务中校验，租户标识不接受客户端输入。 */
@Repository public class MyBatisOrganizationDomain implements OrganizationStructure, com.appnexus.platform.authorization.DataAccessDeclaration.Executor {
 /** @return 原组织领域固定租户查询与写入条件保护的三个配置资源 */
 @Override public java.util.Set<String> enforcedResources(){return java.util.Set.of("organization.type","organization.relation","organization.position", "organization.assignment");}
 private final OrganizationDomainMapper mapper;
 private final com.appnexus.platform.organization.PersonnelCatalog persons;
 private final com.appnexus.platform.authorization.AccessPlanning planning;
 private final com.appnexus.platform.authorization.RowAccessControl rows;
 /** @param mapper 组织固定存储映射 @param persons 人员公开端口 @param planning 实时统一权限计划 @param rows 公共范围执行器，不复制范围合并算法 */
 public MyBatisOrganizationDomain(OrganizationDomainMapper mapper,com.appnexus.platform.organization.PersonnelCatalog persons,com.appnexus.platform.authorization.AccessPlanning planning,com.appnexus.platform.authorization.RowAccessControl rows){this.mapper=mapper;this.persons=persons;this.planning=planning;this.rows=rows;}
 public List<Type> types(){return mapper.types(tenant()).stream().map(r->new Type(id(r,"id"),s(r,"code"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 public Type createType(String code,String name){var id=UUID.randomUUID();mapper.createType(tenant(),id.toString(),code,name);return new Type(id,code,name,true,0);}
 @Transactional public Type updateType(UUID id,String name,boolean enabled,long version){var current=types().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(!enabled&&mapper.typeUsage(tenant(),id.toString())>0)throw new IllegalStateException("TYPE_IN_USE");if(mapper.updateType(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Type(id,current.code(),name,enabled,version+1);}
 public List<Unit> units(){var plan=plan("read");return mapper.scopedUnits(tenant(),plan.rows().type()==com.appnexus.platform.authorization.DataScopeAuthorization.ScopeType.ALL,plan.rows().type()==com.appnexus.platform.authorization.DataScopeAuthorization.ScopeType.ORGANIZATION?plan.rows().organizationIds().stream().sorted().map(UUID::toString).toList():List.of()).stream().map(r->new Unit(id(r,"id"),s(r,"code"),id(r,"typeId"),nullableId(r,"parentId"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 @Transactional public Unit createUnit(String code,UUID typeId,UUID parentId,String name){if(plan("create").rows().type()!=com.appnexus.platform.authorization.DataScopeAuthorization.ScopeType.ALL)throw new SecurityException("ORGANIZATION_CREATE_SCOPE_REQUIRED");validateParent(null,typeId,parentId);var id=UUID.randomUUID();mapper.createUnit(tenant(),id.toString(),code,typeId.toString(),text(parentId),name);return new Unit(id,code,typeId,parentId,name,true,0);}
 @Transactional public Unit updateUnit(UUID id,String name,boolean enabled,long version){mapper.lockUnits(tenant());requireUnit("update",id);var current=unit(id);if(!enabled){var impact=rawImpact(id);if(impact.children()>0||impact.relations()>0||impact.positions()>0||impact.activeAssignments()>0||impact.leaders()>0)throw new IllegalStateException("ORGANIZATION_IN_USE");}if(mapper.updateUnit(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Unit(id,current.code(),current.typeId(),current.parentId(),name,enabled,version+1);}
 @Transactional public Unit moveUnit(UUID id,UUID parentId,long version){mapper.lockUnits(tenant());requireUnit("update",id);if(parentId!=null)requireUnit("update",parentId);var current=unit(id);validateParent(id,current.typeId(),parentId);for(UUID cursor=parentId;cursor!=null;){if(cursor.equals(id))throw new IllegalArgumentException("ORGANIZATION_CYCLE");cursor=unit(cursor).parentId();}if(mapper.moveUnit(tenant(),id.toString(),text(parentId),version)!=1)throw conflict();return new Unit(id,current.code(),current.typeId(),parentId,current.name(),current.enabled(),version+1);}
 public Impact impact(UUID id){requireUnit("read",id);return rawImpact(id);}
 private Impact rawImpact(UUID id){unit(id);var r=mapper.impact(tenant(),id.toString());return new Impact(i(r,"children"),i(r,"relations"),i(r,"positions"),i(r,"activeAssignments"),i(r,"leaders"));}
 public List<Relation> relations(){return mapper.relations(tenant()).stream().map(r->new Relation(id(r,"id"),s(r,"relationType"),id(r,"sourceId"),id(r,"targetId"),n(r,"version"))).toList();}
 public Relation createRelation(String kind,UUID source,UUID target){if(source.equals(target))throw new IllegalArgumentException("SELF_RELATION");unit(source);unit(target);var id=UUID.randomUUID();mapper.createRelation(tenant(),id.toString(),kind,source.toString(),target.toString());return new Relation(id,kind,source,target,0);}
 public void deleteRelation(UUID id,long version){if(mapper.deleteRelation(tenant(),id.toString(),version)!=1)throw conflict();}
 public List<Position> positions(){return mapper.positions(tenant()).stream().map(r->new Position(id(r,"id"),id(r,"organizationId"),s(r,"code"),s(r,"name"),b(r,"enabled"),n(r,"version"))).toList();}
 public Position createPosition(UUID organizationId,String code,String name){if(!unit(organizationId).enabled())throw new IllegalArgumentException("ORGANIZATION_DISABLED");var id=UUID.randomUUID();mapper.createPosition(tenant(),id.toString(),organizationId.toString(),code,name);return new Position(id,organizationId,code,name,true,0);}
 @Transactional public Position updatePosition(UUID id,String name,boolean enabled,long version){var p=positions().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(!enabled&&mapper.positionUsage(tenant(),id.toString())>0)throw new IllegalStateException("POSITION_IN_USE");if(mapper.updatePosition(tenant(),id.toString(),name,enabled,version)!=1)throw conflict();return new Position(id,p.organizationId(),p.code(),name,enabled,version+1);}
 public List<Assignment> assignments(){return mapper.assignments(tenant()).stream().map(r->new Assignment(id(r,"id"),id(r,"personId"),id(r,"positionId"),instant(r,"startsAt"),nullableInstant(r,"endsAt"),b(r,"enabled"),n(r,"version"))).toList();}
 @Transactional public Assignment createAssignment(UUID member,UUID position,Instant starts,Instant ends){if(persons().stream().noneMatch(p->p.id().equals(member)))throw new IllegalArgumentException("PERSON_OR_POSITION_UNAVAILABLE");if(ends!=null&&!ends.isAfter(starts))throw new IllegalArgumentException("INVALID_ASSIGNMENT_PERIOD");var id=UUID.randomUUID();touch(member);if(mapper.createAssignment(tenant(),id.toString(),member.toString(),position.toString(),starts,ends)!=1)throw new IllegalArgumentException("MEMBER_OR_POSITION_UNAVAILABLE");return new Assignment(id,member,position,starts,ends,true,0);}
 @Transactional public Assignment updateAssignment(UUID id,Instant ends,boolean enabled,long version){var a=assignments().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(this::missing);if(ends!=null&&!ends.isAfter(a.startsAt()))throw new IllegalArgumentException("INVALID_ASSIGNMENT_PERIOD");touch(a.personId());if(mapper.updateAssignment(tenant(),id.toString(),ends,enabled,version)!=1)throw conflict();if(!enabled||(ends!=null&&!ends.isAfter(Instant.now())))mapper.removeAssignmentLeaders(tenant(),id.toString());return new Assignment(id,a.personId(),a.positionId(),a.startsAt(),ends,enabled,version+1);}
 public List<Leader> leaders(){return mapper.leaders(tenant()).stream().map(r->new Leader(id(r,"organizationId"),id(r,"assignmentId"))).toList();}
 public void setLeader(UUID organization,UUID assignment,boolean selected){int changed=selected?mapper.addLeader(tenant(),organization.toString(),assignment.toString()):mapper.removeLeader(tenant(),organization.toString(),assignment.toString());if(changed!=1)throw new IllegalArgumentException("LEADER_ASSIGNMENT_UNAVAILABLE");}
 public List<Person> persons(){var bytes=java.nio.ByteBuffer.wrap(tenant());var tenantId=new UUID(bytes.getLong(),bytes.getLong());return persons.active(tenantId).stream().map(p->new Person(p.id(),p.displayName())).toList();}
 /** 使用当前可信实际账号更新人员审计，不将任职人员冒充操作者。 */
 private void touch(UUID person){var request=((ServletRequestAttributes)RequestContextHolder.currentRequestAttributes()).getRequest();var c=(VerifiedTenantContext)request.getAttribute(VerifiedTenantContext.class.getName());persons.touch(c.tenantId(),person,c.accountId());}
 private void validateParent(UUID self,UUID type,UUID parent){if(types().stream().noneMatch(v->v.id().equals(type)&&v.enabled()))throw new IllegalArgumentException("TYPE_UNAVAILABLE");if(parent!=null){var p=unit(parent);if(!p.typeId().equals(type)||!p.enabled()||parent.equals(self))throw new IllegalArgumentException("PARENT_UNAVAILABLE");}}
 /** 仅供已准入写用例检查父链及约束，不能作为对外读取入口；不能因缺少read而阻断合法update。 */
 private Unit unit(UUID id){return mapper.units(tenant()).stream().filter(r->id(r,"id").equals(id)).map(r->new Unit(id(r,"id"),s(r,"code"),id(r,"typeId"),nullableId(r,"parentId"),s(r,"name"),b(r,"enabled"),n(r,"version"))).findFirst().orElseThrow(this::missing);}
 /** 每个操作独立解析，不复用read权作为update准入；缺策略及未知范围由公共执行器拒绝。 */
 private com.appnexus.platform.authorization.AccessPlan plan(String action){var c=context();return planning.plan(com.appnexus.platform.authorization.AccessAuthorization.Subject.tenant(c.accountId(),c.tenantId(),c.memberId()),"organization.unit:"+action,"organization.unit");}
 private void requireUnit(String action,UUID id){if(!rows.allowsOrganization(plan(action),id))throw new SecurityException("ORGANIZATION_DATA_ACCESS_DENIED");}
 private VerifiedTenantContext context(){var attributes=RequestContextHolder.getRequestAttributes();if(!(attributes instanceof ServletRequestAttributes request)||!(request.getRequest().getAttribute(VerifiedTenantContext.class.getName()) instanceof VerifiedTenantContext c))throw new SecurityException("Verified tenant context required");return c;} private IllegalStateException conflict(){return new IllegalStateException("CONCURRENT_MODIFICATION");} private NoSuchElementException missing(){return new NoSuchElementException("ORGANIZATION_OBJECT_NOT_FOUND");}
 private byte[] tenant(){var a=RequestContextHolder.getRequestAttributes();if(!(a instanceof ServletRequestAttributes s)||!(s.getRequest().getAttribute(VerifiedTenantContext.class.getName()) instanceof VerifiedTenantContext c))throw new IllegalStateException("Verified tenant context required");return ByteBuffer.allocate(16).putLong(c.tenantId().getMostSignificantBits()).putLong(c.tenantId().getLeastSignificantBits()).array();}
 private static String s(Map<String,Object> r,String k){return String.valueOf(r.get(k));} private static UUID id(Map<String,Object> r,String k){return UUID.fromString(s(r,k));} private static UUID nullableId(Map<String,Object> r,String k){return r.get(k)==null?null:id(r,k);} private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();} private static int i(Map<String,Object> r,String k){return ((Number)r.get(k)).intValue();} private static boolean b(Map<String,Object> r,String k){Object v=r.get(k);return Boolean.TRUE.equals(v)||(v instanceof Number x&&x.intValue()!=0);} private static String text(UUID id){return id==null?null:id.toString();} private static Instant instant(Map<String,Object> r,String k){Object v=r.get(k);return v instanceof Timestamp t?t.toInstant():(Instant)v;} private static Instant nullableInstant(Map<String,Object> r,String k){return r.get(k)==null?null:instant(r,k);}
}
